static size_t finish_run(pg_client *client,const char *token,const char *text){
 char answer[65536]={0};size_t size=0;int finished=0;double deadline=(double)time(0)+100;
 while(!finished&&(double)time(0)<deadline){pg_event event={0};int status=client->poll(client->context,&event);assert(status>=0);if(!status){struct timespec pause={0,1000000};nanosleep(&pause,0);continue;}if(event.kind==PG_TEXT_DELTA){assert(event.text.size<sizeof(answer)-size);memcpy(answer+size,event.text.data,event.text.size);size+=event.text.size;}if(event.kind==PG_RUN_FINISHED){assert(event.outcome==PG_SUCCESS);finished=1;}}
 if(!finished||!strstr(answer,token)){fprintf(stderr,"Live workflow mismatch: finished=%d, expected=%s, input=%s, answer=%s\n",finished,token,text,answer);if(live_request)fprintf(stderr,"Last system: %s\n",json_object_to_json_string(json_object_array_get_idx(json_object_object_get(live_request,"messages"),0)));}assert(finished&&strstr(answer,token));return size;
}
